import{z as o,x as s,o as e,c as d,q as n,j as A,D as E,d as t,s as i,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"多资产组合","description":"","frontmatter":{"title":"多资产组合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-multiasset.md","filePath":"quant/pf-multiasset.md","lastUpdated":1791413859000}'),u={name:"quant/pf-multiasset.md"};function p(f,a,h,C,c,m){const B=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="多资产组合" tabindex="-1">多资产组合 <a class="header-anchor" href="#多资产组合" aria-label="Permalink to &quot;多资产组合&quot;">​</a></h1><div class="epigraph"><p>跨资产的分散化买的不是「不同的代码」，是不同的宏观环境；当环境只剩一种，多资产的相关矩阵会集体投降。</p><footer>—— 据 Ilmanen, Expected Returns, Wiley, 2011；对照 Markowitz, Journal of Finance, 1952 整理</footer></div><p><a href="/quant/pf-tax-aware">上一课</a>把税写进目标与状态：税后终值、（持仓、税基）增广、不对称带宽。前几课的机器都跑在单一资产池上；缺口是资产类别本身——股票、利率债、信用、商品、外汇的收益生成过程不同，工具与资金形态也不同。本课写多资产组合构建的四件事：结构化估计、货币、杠杆、展期。不重讲<a href="/quant/markowitz">Markowitz</a>的选择问题，也不重写<a href="/quant/risk-parity">风险平价</a>的求解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把资产名单加长不等于多资产组合。新问题有三类。其一，收益的含义不同：债券的收益大头在久期与凸性（<a href="/quant/duration-convexity">久期与凸性</a>），商品的现货之外有<a href="/quant/roll-yield">展期收益</a>与<a href="/quant/contango-backwardation">期货贴水升水</a>，外汇现金有利差（<a href="/quant/carry-everywhere">carry-everywhere</a>）——「均值」对不同类别的生成机制不同，统一当成一个收益率向量会把这些结构抹平。其二，相关是体制的函数：股债相关在增长驱动的年代为负、在通胀冲击下转正，平滑估计的相关矩阵在体制切换时给出完全错误的对冲比。<span class="marginnote">「体制」就是市场所处的宏观环境状态，如「增长上行+低通胀」或「滞胀」。直觉类比：同样的船和帆，顺风与逆风是两种状态；相关矩阵就是帆的用法——只在一种风里校准过的帆，换风时会把船掀翻。</span>其三，低波动资产的分散化贡献大而收益低：不加杠杆的配置会退化成隐蔽的股票基金——分散化的名义与风险的真实不符。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是按「资产类别收益的生成机制不同」重建构建流程：估计层先立宏观因子、把资产写成载荷，协方差按体制分层；执行层把货币对冲、杠杆与展期三笔摩擦各自写清成本来源，全部送进同一个优化器，而不是留在归因里等事后发现。四件事的次序不可换：估计错了，后面的对冲比与杠杆都是精确的错误。</p><h3 id="四件事" tabindex="-1">四件事 <a class="header-anchor" href="#四件事" aria-label="Permalink to &quot;四件事&quot;">​</a></h3><p>结构化估计：先宏观后资产——增长、通胀、实际利率这套低维宏观因子（<a href="/quant/macro-factor-set">宏观因子集</a>）之上，资产是载荷不同的组合；协方差按体制分层估计，动态相关用 <a href="/quant/dcc-portfolio">DCC 动态相关入组合</a>，高频场合接<a href="/quant/realized-covariance">多元已实现协方差</a>。货币：本币收益等于当地收益乘汇率，对冲与否是逐类别的成本收益决策，对冲成本由利差与互换基差决定（<a href="/quant/xccy-basis">xccy-basis</a>），不是默认动作。<span class="marginnote">货币对冲不是免费的：成本约等于两种货币的利差。数字实例：用欧元对冲美元资产，若美元利率比欧元高 2%，持有人每年大约付出 2% 的对冲成本，本币收益被持续侵蚀——是否对冲因此是逐类别的计算题，不是默认开关。</span>杠杆：低波动资产的配置靠杠杆放大到目标风险——风险平价与<a href="/quant/mfd-risk-parity">管理期货风险平价</a>是系统化的做法；杠杆用期货保证金实现而不是融资买券，保证金占用与追缴是真实约束（<a href="/quant/futures-margin">期货保证金</a>），必须进优化器而不是进脚注。展期：期货组合有永续的换月成本与日历选择（<a href="/quant/futures-roll-calendar">期货展期日历</a>），长期持有的「资产」实际是一串带摩擦的滚动头寸。</p>',9)),(e(),A(l,null,{default:E(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22%E5%AE%8F%E8%A7%82%E5%9B%A0%E5%AD%90%EF%BC%9A%E5%A2%9E%E9%95%BF%2F%E9%80%9A%E8%83%80%2F%E5%88%A9%E7%8E%87%22%5D%20--%3E%20MAP%5B%22%E8%B5%84%E4%BA%A7%E8%BD%BD%E8%8D%B7%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20COV%5B%22%E4%BD%93%E5%88%B6%E5%88%86%E5%B1%82%E7%9A%84%E5%8D%8F%E6%96%B9%E5%B7%AE%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20COV%20--%3E%20CUR%5B%22%E8%B4%A7%E5%B8%81%E5%AF%B9%E5%86%B2%E5%86%B3%E7%AD%96%EF%BC%9A%E5%88%A9%E5%B7%AE%E4%B8%8E%E5%9F%BA%E5%B7%AE%22%5D%0A%20%20CUR%20--%3E%20LEV%5B%22%E6%9D%A0%E6%9D%86%E4%B8%8E%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20LEV%20--%3E%20ROLL%5B%22%E5%B1%95%E6%9C%9F%E6%89%A7%E8%A1%8C%E4%B8%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20ROLL%20--%3E%20PF%5B%22%E5%A4%9A%E8%B5%84%E4%BA%A7%E7%BB%84%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"为什么体制分层不可省：2022 年的通胀冲击里股债相关转正，传统股六债四组合录得数十年间最差的年份之一——用平滑历史相关的优化器，没有一格世界里装得下这个输入；它配置的「对冲」在唯一需要兑现的年份失灵。这与上一课讲的政策负债同构：平滑估计便宜了样本内，把凸性风险推迟到危机日结算。杠杆为什么是特性而非缺陷：资本效率的论证是把「安全的资产」放大到与股票同等风险，而不是把股票放大到爆仓——风险预算约束下的杠杆有明确的边界与追缴时间表，把它当洪水猛兽与当免费午餐是同一种错误的两面。展期成本为什么必须进构建：对长期策略，年化几十个基点的展期摩擦复利二十年就是数个百分点的终值差，它应该出现在目标函数里，而不是在事后归因里被「发现」。",-1)),(e(),A(l,null,{default:E(()=>[i(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E4%BD%93%E5%88%B6%E4%B8%80%EF%BC%9A%E5%A2%9E%E9%95%BF%E4%B8%8B%E8%A1%8C%22%5D%20--%3E%20A1%5B%22%E5%88%A9%E7%8E%87%E4%B8%8B%E8%A1%8C%EF%BC%8C%E5%80%BA%E5%88%B8%E6%B6%A8%22%5D%0A%20%20R1%20--%3E%20A2%5B%22%E8%82%A1%E7%A5%A8%E7%9B%88%E5%88%A9%E6%89%BF%E5%8E%8B%EF%BC%8C%E8%82%A1%E7%A5%A8%E8%B7%8C%22%5D%0A%20%20A1%20--%3E%20N%5B%22%E8%82%A1%E5%80%BA%E8%B4%9F%E7%9B%B8%E5%85%B3%EF%BC%9A%E5%80%BA%E5%88%B8%E5%AF%B9%E5%86%B2%E6%9C%89%E6%95%88%22%5D%0A%20%20A2%20--%3E%20N%0A%20%20R2%5B%22%E4%BD%93%E5%88%B6%E4%BA%8C%EF%BC%9A%E9%80%9A%E8%83%80%E5%86%B2%E5%87%BB%22%5D%20--%3E%20B1%5B%22%E5%88%A9%E7%8E%87%E4%B8%8A%E8%A1%8C%EF%BC%8C%E5%80%BA%E5%88%B8%E8%B7%8C%22%5D%0A%20%20R2%20--%3E%20B2%5B%22%E4%BC%B0%E5%80%BC%E4%B8%8E%E7%9B%88%E5%88%A9%E5%8F%8C%E5%8E%8B%EF%BC%8C%E8%82%A1%E7%A5%A8%E4%B9%9F%E8%B7%8C%22%5D%0A%20%20B1%20--%3E%20P%5B%22%E8%82%A1%E5%80%BA%E6%AD%A3%E7%9B%B8%E5%85%B3%EF%BC%9A60%2F40%20%E5%8F%8C%E6%9D%80%22%5D%0A%20%20B2%20--%3E%20P%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">常见误区：以为杠杆爆仓要等「价格归零」。实际上期货杠杆的死法通常是保证金追缴：浮亏把保证金消耗到维持线以下，必须立刻补钱，否则被强制平仓——价格远没到零，仓位已经没了。所以保证金占用与现金储备必须写进优化器的约束，而不是脚注。</span></p><p><span class="marginnote">股债负相关是特定宏观体制的礼物：增长下行时利率下行、债券涨、股票跌；通胀驱动的下行里两者一起跌。多资产组合的分散化，买的是「环境集合」的宽度，不是资产代码的数量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入类别内部的选券与轮动（前面课序的对象），不展开管理期货策略本身（<a href="/quant/mfd-risk-parity">管理期货风险平价</a>与 CTA 课序），不重推风险平价的解。与尾部防御的接口留白：多资产组合在左尾面前的最后一道防线——对冲预算与凸性菜单——是下一课的对象。商品展期的期限结构策略、外汇的套息拥挤，各有专课，此处只进组合层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多资产构建的四件事：结构化估计（宏观因子、体制分层）、货币对冲、杠杆与保证金、展期成本。</li><li>相关是体制的函数：平滑相关在体制切换时集体失效，2022 股债双杀是标准教材。</li><li>低波动资产的杠杆是资本效率工具，约束是保证金与追缴时间表，不是道德判断。</li><li>展期摩擦进目标函数：长期复利下它是构建参数，不是归因发现。</li><li>出处：Ilmanen, <em>Expected Returns</em>, 2011；Markowitz, <em>Journal of Finance</em>, 1952；体制与相关的实证口径据 DCC 与相关性崩溃两课整理。</li></ul>',6))])}const q=o(u,[["render",p]]);export{F as __pageData,q as default};
